diff --git a/src/core/grade.ts b/src/core/grade.ts
index c221deb..85e5bc4 100644
--- a/src/core/grade.ts
+++ b/src/core/grade.ts
@@ -4,10 +4,13 @@ export type Lifecycle = "active" | "superseded" | "expired";
 export interface Grade {
   provenance: Provenance;
   lifecycle: Lifecycle;
+  signatureVerified?: boolean;
 }

 export const rendersAsInstruction = (grade: Grade): boolean =>
-  grade.provenance === "authored" && grade.lifecycle === "active";
+  grade.provenance === "authored" &&
+  grade.lifecycle === "active" &&
+  grade.signatureVerified === true;

 export const renderWarn = (grade: Grade, warn: string): string =>
   rendersAsInstruction(grade) ? `instruction: ${warn}` : `claim: ${warn}`;
diff --git a/src/core/trailers.ts b/src/core/trailers.ts
index fea2056..c2d25c1 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,29 @@
 import type { Provenance } from "./grade.ts";
+import type { CommitSignature } from "./verify.ts";
+import { verifyCommitSignature } from "./verify.ts";

 export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
   const raw = trailers.get("Provenance");
   if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
   return "unknown";
 };
+
+export const verifiedProvenanceOf = (
+  trailers: ReadonlyMap<string, string>,
+  signature: CommitSignature | null
+): Provenance => {
+  const raw = trailers.get("Provenance");
+
+  // Only trust "authored" if cryptographically verified
+  if (raw === "authored") {
+    return verifyCommitSignature(signature) ? "authored" : "unknown";
+  }
+
+  // "inherited" and "reconstructed" are derivable from git history, not self-asserted
+  // but still require verification to prevent spoofing
+  if (raw === "inherited" || raw === "reconstructed") {
+    return verifyCommitSignature(signature) ? raw : "unknown";
+  }
+
+  return "unknown";
+};
diff --git a/src/core/verify.ts b/src/core/verify.ts
new file mode 100644
index 0000000..d4b142f
--- /dev/null
+++ b/src/core/verify.ts
@@ -0,0 +1,10 @@
+export interface CommitSignature {
+  signed: boolean;
+  valid: boolean;
+  fingerprint?: string;
+}
+
+export const verifyCommitSignature = (signature: CommitSignature | null): boolean => {
+  // Only trust explicitly verified GPG signatures
+  return signature?.signed === true && signature?.valid === true;
+};
